"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63563"],{83805(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.secao_com_bloco","status":422,"titulo":"Uma se\xe7\xe3o n\xe3o declara bloco de sistema"},"descricao":{"codigo":"uniplus.estrutura_formulario.secao_com_bloco","requisitos":[],"oQueAconteceu":["Uma p\xe1gina do tipo `SECAO`, que re\xfane itens do formul\xe1rio, traz `bloco` com um dos blocos de sistema (`COMPROVACAO_DOCUMENTAL`, `MODALIDADES_CALCULADAS` ou `REVISAO_E_ACEITE`). O bloco de sistema \xe9 montado pelo sistema a partir da configura\xe7\xe3o do processo e \xe9 uma p\xe1gina \xe0 parte, do tipo `BLOCO`, sem itens. A mensagem \xe9 \\"Uma se\xe7\xe3o n\xe3o declara bloco de sistema.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `paginas[i].bloco`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. O valor de `bloco` que n\xe3o \xe9 nenhum dos tr\xeas \xe9 tratado como ausente, e a se\xe7\xe3o com ele n\xe3o cai aqui.","A estrutura das p\xe1ginas s\xf3 \xe9 conferida quando todas as p\xe1ginas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada p\xe1gina \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as p\xe1ginas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as p\xe1ginas s\xf3 depois que a estrutura das p\xe1ginas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire o `bloco` da se\xe7\xe3o. Se a inten\xe7\xe3o era incluir o bloco de sistema, acrescente uma p\xe1gina pr\xf3pria, com `tipo` igual a `BLOCO` e o `bloco` desejado."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);